UPDATE _image SET image_type = CASE
WHEN image_id = #{li.image_id} AND image_sequence = #{li.image_sequence} THEN #{li.image_type}
ELSE image_type END, image_sequence = CASE
WHEN image_id = #{li.image_id} AND image_sequence = #{li.image_sequence} THEN #{li.image_sequence}
ELSE image_sequence END, image_src = CASE
WHEN image_id = #{li.image_id} AND image_sequence = #{li.image_sequence} THEN #{li.image_src}
ELSE image_src END WHERE (image_id, image_sequence) IN (
(#{li.image_id}, #{li.image_sequence})
)

